// Gross Beat (FL: Gross Beat): tempo-synced time and volume manipulation.
// Form: 824 x 535 (design size; FL opens it at 831 x 561, the size of the
// manual's screenshot, where the bottom row no longer overlaps the slots). Nine automatable parameters (FL's Tags 0..8): the playing
// time slot and volume slot (0..35), the time and volume mix (0..256), the
// volume smoothing attack / release (0..10000, exponential 0..500 ms /
// 0..1000 ms), the volume envelope tension (-256..256), the HOLD switch and
// the scratching time offset (0..65536 = -2 bars..0).
//
// Non-parameter state: 36 time slots and 36 volume slots, each with a name,
// an envelope (1 bar wide; FL's envelope point modes, see gbShape) and its
// transition settings (trigger / position sync, force hold, link, key-held,
// one-shot), the Options menu switches and the editor state (edited envelope,
// snap, step / slide / freeze, slot envelope view).
//
// Time envelopes: the top of the editor is real time, the bottom 8 beats
// (2 bars) back: a point value y means an offset of (1 - y) * 8 beats.
// Volume envelopes: y is the gain (0..1).

import type { FxPluginDef } from '../types';

/** One envelope point: x in beats (0..4), y 0..1, tension -1..1, FL's point mode (0..12). */
export interface GbPoint {
  x: number;
  y: number;
  t: number;
  m: number;
}

export interface GbSlot {
  name: string;
  pts: GbPoint[];
  /** Trigger sync: index into GB_SYNC (Off, 1/4 beat .. 4 beats). */
  trig: number;
  /** Position sync: index into GB_SYNC. */
  pos: number;
  /** Force hold delay: 0 Off, 1 Last, 2 Next. */
  hold: number;
  /** Link slots (a time slot also selects the volume slot with the same number, and vice versa). */
  link: boolean;
  /** Key-held (back to the previous slot on MIDI key release). */
  key: boolean;
  /** One-shot (back to the first slot once done). */
  one: boolean;
}

export interface GbOptions {
  /** Trigger slots from MIDI notes. */
  midi: boolean;
  /** Click reduction: 0 Off, 1 Low (drums), 2 High (melodic). */
  declick: number;
  /** Smoothing attack compensation. */
  comp: boolean;
  /** Remove DC offset. */
  dc: boolean;
  /** HQ resampling. */
  hq: boolean;
  /** View scratching clock. */
  clock: boolean;
}

export const GB_SLOTS = 36;
/** The envelope is one bar (4 beats) wide and two bars (8 beats) high. */
export const GB_BAR = 4;
export const GB_RANGE = 8;
/** Processing latency reported by FL's Gross Beat (samples). */
export const GB_LATENCY = 15;

export const GB_SYNC = ['Off', '1/4 beat', '1/2 beat', '1 beat', '2 beats', '4 beats'];
export const GB_SYNC_BEATS = [0, 0.25, 0.5, 1, 2, 4];
export const GB_HOLD = ['Off', 'Last', 'Next'];
export const GB_SNAP = ['off', '1/16 beat', '1/12 beat', '1/8 beat', '1/6 beat', '1/4 beat', '1/3 beat'];
export const GB_SNAP_BEATS = [0, 1 / 16, 1 / 12, 1 / 8, 1 / 6, 1 / 4, 1 / 3];
export const GB_SNAP_LABELS = ['X', '1/16', '1/12', '1/8', '1/6', '1/4', '1/3'];
export const GB_DECLICK = ['Off', 'Low (drums)', 'High (melodic)'];

/** Point modes offered by Gross Beat's point menu (FL's mode numbers), in menu order. */
export const GB_MODES: { m: number; label: string }[] = [
  { m: 0, label: 'Single curve' },
  { m: 1, label: 'Double curve' },
  { m: 7, label: 'Alt single curve' },
  { m: 8, label: 'Alt double curve' },
  { m: 2, label: 'Hold' },
  { m: 3, label: 'Stairs' },
  { m: 4, label: 'Smooth stairs' },
  { m: 5, label: 'Pulse' },
  { m: 6, label: 'Wave' },
  { m: 9, label: 'Half sine' },
];

// ------------------------------------------------------------ value texts

/** "Slot 1" .. "Slot 36". */
export function gbSlotText(v: number): string {
  return `Slot ${Math.round(v) + 1}`;
}

/** FL's percent text, rounded half away from zero: 96/256 -> "38%", -32/256 -> "-13%". */
export function gbPctText(v: number, full = 256): string {
  const p = (v / full) * 100;
  const r = Math.sign(p) * Math.round(Math.abs(p));
  return `${r === 0 ? 0 : r}%`;
}

/** Volume smoothing time in ms for a control value (0..10000): max * (501^x - 1) / 500. */
export function gbSmoothMs(v: number, maxMs: number): number {
  const x = Math.min(1, Math.max(0, v / 10000));
  return (maxMs * (Math.pow(501, x) - 1)) / 500;
}

export function gbAttText(v: number): string {
  return `${gbSmoothMs(v, 500).toFixed(2)}ms`;
}

export function gbRelText(v: number): string {
  return `${gbSmoothMs(v, 1000).toFixed(2)}ms`;
}

/** Scratch offset in beats (0..8) for the time offset control value (65536 = 0, 0 = 2 bars). */
export function gbOffsetBeats(v: number): number {
  return ((65536 - Math.min(65536, Math.max(0, v))) * GB_RANGE) / 65536;
}

/** FL's time offset text "-bar:beat:tick" (bars of 4 beats, 96 ticks per beat; ticks rounded without carry). */
export function gbOffsetText(v: number): string {
  const b = gbOffsetBeats(v);
  const whole = Math.floor(b + 1e-9);
  const bar = Math.floor(whole / 4);
  const beat = whole % 4;
  const tick = Math.round((b - whole) * 96);
  return `-${String(bar).padStart(3, '0')}:${String(beat).padStart(2, '0')}:${String(tick).padStart(3, '0')}`;
}

/** Offset (beats) -> time envelope value. */
export const gbOff = (beats: number): number => 1 - beats / GB_RANGE;

// --------------------------------------------------------- curve maths
// FL's envelope segment shapes (shared with the automation clip evaluator,
// docs/research/automation.md §4). Segment i runs from point i-1 to point i
// and takes point i's mode and tension.

const LN_1E6 = Math.log(1e6);

function rint(x: number): number {
  const f = Math.floor(x);
  const d = x - f;
  if (d > 0.5) return f + 1;
  if (d < 0.5) return f;
  return f % 2 === 0 ? f : f + 1;
}

/** Steps / cycles of Stairs, Smooth stairs, Pulse and Wave: 1000 at t = 0, 16 at |t| = 0.5, 0 at |t| = 1. */
export function gbStepCount(t: number): number {
  const e = Math.fround(1 - 0.6 * Math.min(1, Math.abs(t)));
  return rint((Math.exp(LN_1E6 * e) - 1) * 0.001);
}

/** Single curve with tension t (FL's exponential curve, 10^(6|t|) span). */
export function gbSingle(u: number, t: number): number {
  if (t === 0) return u;
  const L = LN_1E6 * Math.abs(t);
  const k = Math.expm1(L);
  return t < 0 ? Math.expm1(L * u) / k : 1 - Math.expm1(L * (1 - u)) / k;
}

function single2(u: number, t: number): number {
  const x = t > 0 ? 1 - u : u;
  return u - t * (x ** 6 - x);
}

function single3(u: number, t: number): number {
  if (t === 0) return u;
  const a = 1 - (1 - Math.max(0.9 * Math.abs(t), 2 ** -16)) ** 3;
  if (t < 0) return ((1 - a) * u) / (1 - a * u);
  const w = 1 - u;
  return 1 - ((1 - a) * w) / (1 - a * w);
}

function mirror(u: number, t: number, f: (x: number, t: number) => number): number {
  return u < 0.5 ? 0.5 * f(2 * u, t) : 1 - 0.5 * f(2 * (1 - u), t);
}

/** Shape S(u) of a segment (u 0..1) for FL point mode m and tension t; S(1) = 1. */
export function gbShape(m: number, u: number, tension: number): number {
  if (u >= 1) return 1;
  if (!(u > 0)) u = 0;
  const t = tension > 1 ? 1 : tension < -1 ? -1 : tension || 0;
  switch (m) {
    case 0: return gbSingle(u, t);
    case 1: return mirror(u, t, gbSingle);
    case 2: return 0;
    case 3: {
      const s = t >= 0 ? 1 : -1;
      const n = gbStepCount(t) + (t >= 0 ? 2 : 1);
      return rint(u * n - s / 2) / (n - s);
    }
    case 4: {
      const n = gbStepCount(t) + 1;
      const d = u * n - 0.5;
      const j = rint(d - 0.5);
      const x = 2 * (d - j) - 1;
      const e = t >= 0 ? x * x * x : Math.sign(x) * (1 - (1 - Math.abs(x)) ** 3);
      return (j + 0.5 * e + 1) / n;
    }
    case 5: {
      const mm = 2 * (gbStepCount(t) + 1);
      return rint(u * mm - (t >= 0 ? 0.5 : -0.5)) % 2 === 0 ? 0 : 1;
    }
    case 6: {
      const n = gbStepCount(t);
      if (t > 0 && n === 0) return u;
      const f = n + 0.5;
      if (t < 0) return 0.5 * (Math.sin(2 * Math.PI * (u * f + 0.75)) + 1);
      const d = u * f - 0.5;
      return Math.abs(2 * (d - rint(d - 0.5)) - 1);
    }
    case 7: return single2(u, t);
    case 8: return mirror(u, t, single2);
    case 9: {
      const q = t > 0 ? Math.sin((Math.PI / 2) * u) : 1 - Math.cos((Math.PI / 2) * u);
      const a = Math.abs(t);
      return (1 - a) * u + a * q;
    }
    case 11: return single3(u, t);
    case 12: return mirror(u, t, single3);
    default: {
      // Smooth (10), isolated: smoothstep blended toward the line by |t|
      const h = u * u * (3 - 2 * u);
      return u + (h - u) * (1 - Math.abs(t));
    }
  }
}

/**
 * Envelope value at x beats. Points are sorted by x; at a shared x the last
 * point wins (a zero-length segment is a jump). The first point's value holds
 * before it, the last point's after it.
 */
export function gbEval(pts: readonly GbPoint[], x: number): number {
  const n = pts.length;
  if (n === 0) return 1;
  if (x < pts[0].x) return pts[0].y;
  if (x >= pts[n - 1].x) return pts[n - 1].y;
  let lo = 0, hi = n - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (pts[mid].x <= x) lo = mid; else hi = mid;
  }
  const a = pts[lo], b = pts[hi];
  const u = (x - a.x) / (b.x - a.x);
  const v = a.y + (b.y - a.y) * gbShape(b.m, u, b.t);
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

// ------------------------------------------------------- slot banks

export function gbEmptySlot(name = ''): GbSlot {
  return { name, pts: [{ x: 0, y: 1, t: 0, m: 2 }, { x: GB_BAR, y: 1, t: 0, m: 2 }], trig: 5, pos: 5, hold: 0, link: false, key: false, one: false };
}

/** FL's default bank: 36 unnamed flat slots (trigger and position sync 4 beats). */
export function gbEmptyBank(): GbSlot[] {
  return Array.from({ length: GB_SLOTS }, () => gbEmptySlot());
}

// Factory presets, decoded from FL's preset states (flfxhost --preset NAME
// --save-state) into a compact text form: slots separated by '|', each
// "name~flags~points" with flags = trig pos hold link key one, and points
// "<mode a..m><dx>.<y>[:<t>]" in base 36 (x in 1/3840 beat steps from the
// previous point, y in 1/49152, tension in 1/2000). An empty point list is a
// flat line at the top. Options = map dc comp hq clock declick.
const XQ = 3840, YQ = 49152, TQ = 2000;

function decodePoints(s: string): GbPoint[] {
  if (!s) return [{ x: 0, y: 1, t: 0, m: 2 }, { x: GB_BAR, y: 1, t: 0, m: 2 }];
  const pts: GbPoint[] = [];
  let x = 0;
  for (const tok of s.split(' ')) {
    const m = tok.charCodeAt(0) - 97;
    let body = tok.slice(1);
    let t = 0;
    const c = body.indexOf(':');
    if (c >= 0) { t = parseInt(body.slice(c + 1), 36) / TQ; body = body.slice(0, c); }
    const d = body.indexOf('.');
    x += parseInt(body.slice(0, d), 36);
    pts.push({ x: x / XQ, y: parseInt(body.slice(d + 1), 36) / YQ, t, m });
  }
  return pts;
}

export function gbDecodeBank(enc: string): { tslots: GbSlot[]; vslots: GbSlot[] } {
  const all = enc.split('|').map((s) => {
    const [name, f, pts] = s.split('~');
    return {
      name, pts: decodePoints(pts ?? ''),
      trig: Number(f[0]), pos: Number(f[1]), hold: Number(f[2]), link: f[3] === '1', key: f[4] === '1', one: f[5] === '1',
    } as GbSlot;
  });
  return { tslots: all.slice(0, GB_SLOTS), vslots: all.slice(GB_SLOTS, 2 * GB_SLOTS) };
}

const PARAM_KEYS = ['tslot', 'vslot', 'tmix', 'vmix', 'att', 'rel', 'tns', 'hold', 'offset'];

let presetCache: { name: string; params: Record<string, unknown> }[] | null = null;

/** FL's factory presets (parameters, both slot banks and the Options switches). */
export function gbPresets(): { name: string; params: Record<string, unknown> }[] {
  if (presetCache) return presetCache;
  presetCache = FL_PRESETS.map(([name, values, o, enc]) => {
    const params: Record<string, unknown> = {};
    PARAM_KEYS.forEach((k, i) => { params[k] = values[i]; });
    return {
      name,
      params: {
        ...params,
        ...gbDecodeBank(enc),
        map: Number(o[0]) === 1 ? 1 : 0,
        opt: { midi: true, dc: o[1] === '1', comp: o[2] === '1', hq: o[3] === '1', clock: o[4] === '1', declick: Number(o[5]) },
      },
    };
  });
  return presetCache;
}

export function gbDefaultOptions(): GbOptions {
  return { midi: true, declick: 1, comp: false, dc: false, hq: true, clock: true };
}

/** Repair one stored slot (fields missing from older saves, bad values). */
export function gbNormalizeSlot(s: unknown, fallback: GbSlot): GbSlot {
  const o = (s && typeof s === 'object' ? s : {}) as Partial<GbSlot>;
  const pts = Array.isArray(o.pts) && o.pts.length > 0
    ? o.pts.map((p) => ({
      x: Math.min(GB_BAR, Math.max(0, Number(p?.x) || 0)),
      y: Math.min(1, Math.max(0, Number.isFinite(Number(p?.y)) ? Number(p?.y) : 1)),
      t: Math.min(1, Math.max(-1, Number(p?.t) || 0)),
      m: Number.isInteger(p?.m) && (p?.m as number) >= 0 && (p?.m as number) <= 12 ? (p?.m as number) : 0,
    }))
    : fallback.pts.map((p) => ({ ...p }));
  for (let i = 1; i < pts.length; i++) if (pts[i].x < pts[i - 1].x) pts[i].x = pts[i - 1].x;
  if (pts.length < 2) pts.push({ ...pts[0], x: GB_BAR });
  const idx = (v: unknown, n: number, d: number) => (Number.isInteger(v) && (v as number) >= 0 && (v as number) < n ? (v as number) : d);
  return {
    name: typeof o.name === 'string' ? o.name : fallback.name,
    pts,
    trig: idx(o.trig, GB_SYNC.length, fallback.trig),
    pos: idx(o.pos, GB_SYNC.length, fallback.pos),
    hold: idx(o.hold, GB_HOLD.length, fallback.hold),
    link: typeof o.link === 'boolean' ? o.link : fallback.link,
    key: typeof o.key === 'boolean' ? o.key : fallback.key,
    one: typeof o.one === 'boolean' ? o.one : fallback.one,
  };
}

function normalizeBank(v: unknown): GbSlot[] {
  const a = Array.isArray(v) ? v : [];
  return Array.from({ length: GB_SLOTS }, (_, i) => (i < a.length ? gbNormalizeSlot(a[i], gbEmptySlot()) : gbEmptySlot()));
}

export const def: FxPluginDef = {
  id: 'grossbeat',
  name: 'Gross Beat',
  category: 'Misc',
  width: 831,
  height: 561,
  description: 'Tempo-synced time and volume manipulation: repeats, stutters, scratches and gates',
  params: [
    { key: 'tslot', name: 'Time slot', index: 0, min: 0, max: 35, def: 0, format: gbSlotText, parse: (n) => Math.round(n) - 1 },
    { key: 'vslot', name: 'Volume slot', index: 1, min: 0, max: 35, def: 0, format: gbSlotText, parse: (n) => Math.round(n) - 1 },
    { key: 'tmix', name: 'Time mix', index: 2, min: 0, max: 256, def: 256, format: (v) => gbPctText(v) },
    { key: 'vmix', name: 'Volume mix', index: 3, min: 0, max: 256, def: 256, format: (v) => gbPctText(v) },
    { key: 'att', name: 'Volume smoothing attack', index: 4, min: 0, max: 10000, def: 1765, format: gbAttText },
    { key: 'rel', name: 'Volume smoothing release', index: 5, min: 0, max: 10000, def: 5000, format: gbRelText },
    { key: 'tns', name: 'Volume envelope tension', index: 6, min: -256, max: 256, def: 0, bipolar: true, format: (v) => gbPctText(v) },
    { key: 'hold', name: 'Hold delay (bar repeat)', index: 7, min: 0, max: 1, def: 0, format: () => '' },
    { key: 'offset', name: 'Time offset (scratching)', index: 8, min: 0, max: 65536, def: 65536, format: gbOffsetText },
  ],
  get presets() { return gbPresets(); },
  state: () => ({
    tslots: gbEmptyBank(),
    vslots: gbEmptyBank(),
    opt: gbDefaultOptions(),
    /** Edited envelope: 0 time travel, 1 volume. */
    map: 0,
    /** Snap: index into GB_SNAP. */
    snap: 3,
    step: false,
    slide: false,
    freeze: false,
    /** Slot buttons show their envelopes instead of names. */
    zoom: false,
  }),
  normalize: (p) => {
    const o = (p.opt && typeof p.opt === 'object' ? p.opt : {}) as Partial<GbOptions>;
    const d = gbDefaultOptions();
    return {
      ...p,
      tslots: normalizeBank(p.tslots),
      vslots: normalizeBank(p.vslots),
      opt: {
        midi: typeof o.midi === 'boolean' ? o.midi : d.midi,
        declick: Number.isInteger(o.declick) && (o.declick as number) >= 0 && (o.declick as number) <= 2 ? o.declick : d.declick,
        comp: typeof o.comp === 'boolean' ? o.comp : d.comp,
        dc: typeof o.dc === 'boolean' ? o.dc : d.dc,
        hq: typeof o.hq === 'boolean' ? o.hq : d.hq,
        clock: typeof o.clock === 'boolean' ? o.clock : d.clock,
      },
      map: p.map === 1 ? 1 : 0,
      snap: Number.isInteger(p.snap) && (p.snap as number) >= 0 && (p.snap as number) < GB_SNAP.length ? p.snap : 3,
    };
  },
};

